CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 TEXT NOT NULL DEFAULT 0, c1 REAL DEFAULT 'd', c2 VARCHAR(10), c3 NUMERIC UNIQUE, c4 REAL);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(-272, 'chi', 1, 2, 1e-7);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES('phi', 4.5e-310, 'MU', '0x1F', 'x_y');
INSERT OR IGNORE INTO t0(c0, c1, c2, c3, c4) VALUES(0, 'tau', 'delta', x'730e', 595.852);
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 INTEGER, c1 NUMERIC DEFAULT 'd', c2 NUMERIC DEFAULT 'd', c3 BLOB NOT NULL DEFAULT 0, c4 BLOB NOT NULL DEFAULT 0, ref INTEGER REFERENCES t0(id));
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4, ref) VALUES(9223372036854775807, 4, 'alpha', x'08', 'gamma', NULL);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4, ref) VALUES(-5, -1, -665.0216, -210, x'7674b427', 2);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4, ref) VALUES(x'7623e7ccf9ba', x'30', NULL, 3, 0, 5);
CREATE TABLE t2(id INTEGER PRIMARY KEY, c0 BLOB UNIQUE, c1 REAL CHECK(c1 IS NULL OR length(c1) < 40), c2 BLOB NOT NULL DEFAULT 0, c3 INTEGER COLLATE NOCASE, ref INTEGER REFERENCES t1(id));
INSERT OR IGNORE INTO t2(c0, c1, c2, c3, ref) VALUES(NULL, 'nu', x'', 0.1, 6);
SELECT json_valid('[1,"two",3.0,true,false,null,{"k":"v"}]'), json('[1,"two",3.0,true,false,null,{"k":"v"}]'), json_type('[1,"two",3.0,true,false,null,{"k":"v"}]'), json_array_length('[1,"two",3.0,true,false,null,{"k":"v"}]'), json_extract('[1,"two",3.0,true,false,null,{"k":"v"}]', '$.a', '$[1]', '$.b[2].c'), '[1,"two",3.0,true,false,null,{"k":"v"}]' -> '$.b', '[1,"two",3.0,true,false,null,{"k":"v"}]' ->> '$.n.m.o';
SELECT key, value, type FROM json_each('[1,"two",3.0,true,false,null,{"k":"v"}]') ORDER BY key;
SELECT json_set('[1,"two",3.0,true,false,null,{"k":"v"}]', '$.z', 1), json_insert('[1,"two",3.0,true,false,null,{"k":"v"}]', '$.a', 2), json_remove('[1,"two",3.0,true,false,null,{"k":"v"}]', '$.a'), json_patch('{"a":1}', '{"b":2}');
SELECT json_group_array(id), json_group_object(CAST(id AS TEXT), id) FROM t0;
SELECT json_object('id', id, 'v', id) FROM t0 ORDER BY id LIMIT 4;
